};

const formVariant = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { duration: 0.2 } },
    exit:   { opacity: 0, transition: { duration: 0.15 } },
};

// ─── Main Component ───────────────────────────────────────────────────────────

const Login = ({ defaultRole = 'student' }) => {
    const [role, setRole]               = useState(defaultRole);
    const [email, setEmail]             = useState('');
    const [password, setPassword]       = useState('');
    const [rememberMe, setRememberMe]   = useState(false);
    const [showPassword, setShowPassword] = useState(false);
    const [loading, setLoading]         = useState(false);
    const [error, setError]             = useState('');
    const [fieldErrors, setFieldErrors] = useState({});
    const [success, setSuccess]         = useState(false);

    const navigate = useNavigate();

    // Load remembered email on mount
    useEffect(() => {
        const saved = localStorage.getItem('rememberedEmail');
        if (saved) { setEmail(saved); setRememberMe(true); }
    }, []);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        setFieldErrors({});

        try {
            const res  = await fetch(`${API_URL}/api/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, password, role }),
            });
            const data = await res.json();

            if (res.ok) {
                localStorage.setItem('user', JSON.stringify(data.user));
                localStorage.setItem('isAuthenticated', 'true');
                if (rememberMe) localStorage.setItem('rememberedEmail', email);
                else            localStorage.removeItem('rememberedEmail');

                setSuccess(true);
                await new Promise(r => setTimeout(r, 1400));
                navigate(data.user?.role === 'admin' ? '/admin/dashboard' : '/app/dashboard');
            } else {
                const msg = data.error || 'Invalid credentials';
                setError(msg);
                const low = msg.toLowerCase();
                if (low.includes('email'))    setFieldErrors({ email: true });
                if (low.includes('password') || low.includes('credentials'))
                    setFieldErrors({ email: true, password: true });
            }
        } catch {
            setError('Could not connect to server');
        } finally {
            setLoading(false);
        }
    };

    // ── Shared input class builder ──────────────────────────────────────────
    const inputCls = (hasError) =>
        `w-full rounded-xl pl-10 pr-4 py-3 text-[13px] outline-none transition-all duration-150 ` +
        (hasError
            ? 'bg-red-500/5 border border-red-500/40 text-[#F5F5F5] placeholder:text-[#3A3A3A] focus:ring-1 focus:ring-red-500/60'
            : 'bg-black/20 border border-white/8 text-[#F5F5F5] placeholder:text-[#3A3A3A] focus:ring-1 focus:ring-[var(--primary)] focus:border-[var(--primary)]');

    return (
        <div
            className="min-h-screen flex overflow-hidden relative"
            style={{ backgroundColor: 'var(--bg-body)', color: 'var(--text-main)', fontFamily: 'var(--font-sans)' }}
        >
            {/* ── Full-page background (right panel grid) ─────────────────── */}
            <div className="absolute inset-0 z-0 pointer-events-none overflow-hidden">
                <AuthBgRight className="absolute inset-0 w-full h-full" />
            </div>

            {/* ══════════════════ LEFT BRAND PANEL ═══════════════════════════ */}
            <div
                className="hidden lg:flex relative w-[48%] flex-shrink-0 flex-col min-h-screen px-16 py-12 overflow-hidden border-r"
                style={{ backgroundColor: '#0D0D0D', borderColor: '#1A1A1A' }}
            >
                {/* Panel background grid */}
                <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none">
                    <AuthBgLeft className="absolute inset-0 w-full h-full" />
                </div>

                <div className="relative z-10 flex flex-col h-full">
                    {/* Logo */}
                    <Link to="/" className="flex items-center gap-3 flex-shrink-0 cursor-pointer hover:opacity-80 transition-opacity">
                        <LogoSVG className="w-auto h-12" />
                    </Link>

                    {/* Headline + Illustration */}
                    <div className="flex-1 flex flex-col justify-center py-12">
                        <p
                            className="text-[11px] font-semibold uppercase tracking-widest mb-6"
                            style={{ color: 'var(--primary)' }}
                        >
                            Placement Intelligence Platform
                        </p>
                        <h2
                            className="text-[44px] font-bold leading-[1.05] tracking-tighter mb-6"
                            style={{ color: 'var(--text-main)' }}
                        >
                            Your campus.<br />
                            Your placements.<br />
                            <span style={{ color: 'var(--primary)' }}>Centralized.</span>
                        </h2>
                        <p className="text-[15px] leading-relaxed mb-12 max-w-[340px]" style={{ color: '#525252' }}>
                            SAARTHI Nexus is the all-in-one placement platform built for PICT — eligibility filtering, AI guidance, and live analytics.
                        </p>

                        {/* Illustration card - Enlarged and Centered */}
                        <div
                            className="rounded-2xl w-full max-w-[500px] mx-auto p-4 relative mt-4 border"
                            style={{ backgroundColor: 'var(--bg-card)', borderColor: '#2A2A2A' }}
                        >
                            <AuthIllustration />
                        </div>
                    </div>

                    {/* Stats strip */}
                    <div className="flex-shrink-0 flex items-center pt-6 border-t" style={{ borderColor: '#1A1A1A' }}>
                        {[
                            { num: '1,200+', label: 'Students enrolled' },
                            { num: '58',     label: 'Companies visited' },
                            { num: '78%',    label: 'Placement rate'    },
                        ].map((s, i) => (
                            <div
                                key={i}
                                className={`flex-1 ${i < 2 ? 'border-r pr-4 mr-4' : ''}`}
                                style={{ borderColor: '#1A1A1A' }}
                            >
                                <div
                                    className="text-[22px] font-bold leading-none mb-1 tracking-tight"
                                    style={{ color: 'var(--primary)' }}
                                >
                                    {s.num}
                                </div>
                                <div className="text-[11px]" style={{ color: '#525252' }}>
                                    {s.label}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* ══════════════════ RIGHT FORM PANEL ═══════════════════════════ */}
            <div className="flex-1 relative z-10 flex items-start lg:items-center justify-center px-6 py-12 overflow-y-auto">

                {/* Animated form card */}
                <motion.div
                    className="w-full max-w-[400px]"
                    variants={pageVariant}
                    initial="hidden"
                    animate="visible"
                >
                    <AnimatePresence mode="wait">

                        {/* ── SUCCESS STATE ─────────────────────────────── */}
                        {success ? (
                            <motion.div
                                key="success"
                                variants={successVariant}
                                initial="hidden"
                                animate="visible"
                                exit="exit"
                                className="flex flex-col items-center justify-center py-16 text-center"
                            >
                                <AuthSuccess />
                                <h2 className="text-[22px] font-bold mt-6 mb-2 tracking-tighter" style={{ color: 'var(--text-main)' }}>
                                    You're in!
                                </h2>
                                <p className="text-[14px]" style={{ color: '#525252' }}>
                                    Redirecting to your dashboard…
                                </p>
                                <div className="mt-6 w-32 h-[2px] rounded-full overflow-hidden" style={{ background: '#1A1A1A' }}>
                                    <motion.div
                                        className="h-full rounded-full"
                                        style={{ backgroundColor: 'var(--success)' }}
                                        initial={{ width: '0%' }}
                                        animate={{ width: '100%' }}
                                        transition={{ duration: 1.2, ease: 'linear' }}
                                    />
                                </div>
                            </motion.div>

                        ) : (

                        /* ── FORM STATE ───────────────────────────────── */
                        <motion.div
                            key="form"
                            variants={formVariant}
                            initial="hidden"
                            animate="visible"
                            exit="exit"
                            className="w-full"
                        >
                            {/* Mobile logo */}
                            <Link to="/" className="flex lg:hidden items-center gap-2 mb-8 cursor-pointer hover:opacity-80 transition-opacity">
                                <div
                                    className="w-7 h-7 rounded-md flex items-center justify-center text-[10px] font-bold text-black"
                                    style={{ backgroundColor: 'var(--primary)' }}
                                >
                                    SN
                                </div>
                                <span className="text-[13px] font-semibold tracking-tight" style={{ color: '#A3A3A3' }}>
                                    SAARTHI Nexus
                                </span>
                            </Link>

                            {/* Heading */}
                            <h1
                                className="text-[30px] font-bold tracking-tighter leading-tight mb-1"
                                style={{ color: 'var(--text-main)' }}
                            >
                                Welcome back
                            </h1>
                            <p className="text-[14px] mb-8 leading-relaxed" style={{ color: '#525252' }}>
                                Sign in to access your placement portal.
                            </p>

                            {/* ── Role Switcher (layoutId sliding pill) ── */}
                            <div
                                className="relative flex rounded-xl p-1 mb-7 border"
                                style={{ backgroundColor: '#0D0D0D', borderColor: '#2A2A2A' }}
                            >
                                {(['student', 'admin']).map((r) => (
                                    <button
                                        key={r}
                                        type="button"
                                        onClick={() => { setRole(r); setFieldErrors({}); setError(''); }}
                                        className="relative flex-1 flex items-center justify-center gap-2 py-2.5 px-4 rounded-lg text-[13px] font-medium z-10 transition-colors duration-150 border-none cursor-pointer"
                                        style={{
                                            background: 'transparent',
                                            color: role === r ? 'var(--text-main)' : '#525252',
                                        }}
                                    >
                                        {/* Sliding pill background */}
                                        {role === r && (
                                            <motion.div
                                                layoutId="role-pill"
                                                className="absolute inset-0 rounded-lg"
                                                style={{ backgroundColor: '#1A1A1A', border: '1px solid #2A2A2A' }}
                                                transition={{ type: 'spring', stiffness: 300, damping: 28 }}
                                            />
                                        )}
                                        <span className="relative z-10 flex items-center gap-2">
                                            {r === 'student' ? <User size={14} /> : <ShieldCheck size={14} />}
                                            <span className="capitalize">{r}</span>
                                        </span>
                                    </button>
                                ))}
                            </div>

                            {/* ── Form ──────────────────────────────────── */}
                            <form onSubmit={handleSubmit}>
                                {/* Error banner */}
                                <AnimatePresence>
                                    {error && (
                                        <motion.div
                                            key="err"
                                            initial={{ opacity: 0, y: -6 }}
                                            animate={{ opacity: 1, y: 0 }}
                                            exit={{ opacity: 0, y: -4 }}
                                            className="flex items-start gap-3 rounded-xl px-4 py-3 mb-5 border"
                                            style={{ background: 'rgba(239,68,68,0.06)', borderColor: 'rgba(239,68,68,0.22)' }}
                                        >
                                            <div className="w-[3px] self-stretch rounded-full flex-shrink-0" style={{ background: '#EF4444', minHeight: 16 }} />
                                            <div>
                                                <p className="text-[12px] font-semibold mb-0.5" style={{ color: '#EF4444' }}>Login failed</p>
                                                <p className="text-[12px] leading-relaxed" style={{ color: 'rgba(239,68,68,0.75)' }}>{error}</p>
                                            </div>
                                        </motion.div>
                                    )}
                                </AnimatePresence>

                                {/* Email */}
                                <div className="mb-4">
                                    <label
                                        className="block text-[10px] font-semibold uppercase tracking-widest mb-2"
                                        style={{ color: '#A3A3A3' }}
                                    >
                                        Email Address
                                    </label>
                                    <div className="relative">
                                        <Mail
                                            size={15}
                                            className="absolute left-3.5 top-1/2 -translate-y-1/2 pointer-events-none z-10"
                                            style={{ color: fieldErrors.email ? '#EF4444' : '#525252' }}
                                        />
                                        <input
                                            type="email"
                                            placeholder="name@college.edu"
                                            value={email}
                                            onChange={(e) => { setEmail(e.target.value); if (fieldErrors.email) setFieldErrors({}); setError(''); }}
                                            required
                                            className={inputCls(!!fieldErrors.email)}
                                        />
                                    </div>
                                </div>

                                {/* Password */}
                                <div className="mb-5">
                                    <label
                                        className="block text-[10px] font-semibold uppercase tracking-widest mb-2"
                                        style={{ color: '#A3A3A3' }}
                                    >
                                        Password
                                    </label>
                                    <div className="relative">
                                        <Lock
                                            size={15}
                                            className="absolute left-3.5 top-1/2 -translate-y-1/2 pointer-events-none z-10"
                                            style={{ color: fieldErrors.password ? '#EF4444' : '#525252' }}
                                        />
                                        <input
                                            type={showPassword ? 'text' : 'password'}
                                            placeholder="••••••••"
                                            value={password}
                                            onChange={(e) => { setPassword(e.target.value); if (fieldErrors.password) setFieldErrors({}); setError(''); }}
                                            required
                                            className={inputCls(!!fieldErrors.password) + ' pr-11'}
                                        />
                                        <button
                                            type="button"
                                            onClick={() => setShowPassword(!showPassword)}
                                            className="absolute right-3.5 top-1/2 -translate-y-1/2 transition-colors duration-150 bg-transparent border-none cursor-pointer p-0.5"
                                            style={{ color: '#525252' }}
                                        >
                                            {showPassword ? <EyeOff size={15} /> : <Eye size={15} />}
                                        </button>
                                    </div>
                                </div>

                                {/* Remember me */}
                                <div className="flex items-center justify-between mb-7">
                                    <label className="flex items-center gap-2.5 cursor-pointer select-none">
                                        <div className="relative flex-shrink-0">
                                            <input
                                                type="checkbox"
                                                checked={rememberMe}
                                                onChange={(e) => setRememberMe(e.target.checked)}
                                                className="sr-only peer"
                                            />
                                            <div
                                                className="w-9 h-5 rounded-full border transition-all duration-200 peer-checked:border-orange-500/60"
                                                style={{ backgroundColor: '#1A1A1A', borderColor: '#2A2A2A' }}
                                            />
                                            <div
                                                className="absolute top-[3px] left-[3px] w-[14px] h-[14px] rounded-full shadow-sm transition-all duration-200 peer-checked:translate-x-4"
                                                style={{ backgroundColor: '#525252' }}
                                                // Framer can't easily reach peer-checked here, CSS peer handles it
                                            />
                                        </div>
                                        <span className="text-[12px]" style={{ color: '#525252' }}>Remember me</span>
                                    </label>
                                </div>

                                {/* Submit */}
                                <motion.button
                                    type="submit"
                                    disabled={loading}
                                    whileHover={!loading ? { scale: 1.015 } : {}}
                                    whileTap={!loading ? { scale: 0.975 } : {}}
                                    className="w-full font-semibold text-[14px] py-3 rounded-xl border-none flex items-center justify-center gap-2 cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed"
                                    style={{ backgroundColor: 'var(--primary)', color: '#000' }}
                                    transition={{ type: 'spring', stiffness: 400, damping: 20 }}
                                >
                                    {loading
                                        ? <div className="w-4 h-4 border-2 border-black/20 border-t-black rounded-full animate-spin" />
                                        : <><span>Sign In</span><ArrowRight size={15} /></>
                                    }
                                </motion.button>
                            </form>

                            {/* Divider */}
                            <div className="flex items-center gap-3 my-6">
                                <div className="flex-1 h-px" style={{ backgroundColor: '#1A1A1A' }} />
                                <span className="text-[11px]" style={{ color: '#3A3A3A' }}>or</span>
                                <div className="flex-1 h-px" style={{ backgroundColor: '#1A1A1A' }} />
                            </div>

                            {/* Footer */}
                            <p className="text-[13px] text-center" style={{ color: '#525252' }}>
                                {role === 'student' ? (
                                    <>Don't have an account?{' '}
                                        <Link to="/signup" className="font-medium transition-opacity hover:opacity-80" style={{ color: 'var(--primary)' }}>
                                            Create Account
                                        </Link>
                                    </>
                                ) : (
                                    <>Forgot admin credentials?{' '}
                                        <a href="mailto:support@saarthi.nexus" className="font-medium transition-opacity hover:opacity-80" style={{ color: 'var(--primary)' }}>
                                            Contact IT Support
                                        </a>
                                    </>
                                )}
                            </p>

                        </motion.div>
                        )}

                    </AnimatePresence>
                </motion.div>
            </div>
        </div>
    );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { User, Lock, Mail, Hash, BookOpen, AlertCircle, CheckCircle2, LogOut, GraduationCap, Save, Award, FileText, UploadCloud } from 'lucide-react';
import { API_URL } from '../config';
import '../styles/Profile.css';

const Profile = () => {
    const navigate = useNavigate();
    const user = JSON.parse(localStorage.getItem('user') || '{}');
    const [currentPassword, setCurrentPassword] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState({ type: '', text: '' });

    const [fullName, setFullName] = useState(user.fullName || '');
    const [department, setDepartment] = useState(user.department || '');
    const [profilePicture, setProfilePicture] = useState(user.profilePicture || null);
    const [infoLoading, setInfoLoading] = useState(false);
    const [infoMessage, setInfoMessage] = useState({ type: '', text: '' });

    // AI/Resume fields state (from Resume Extraction)
    const [skills, setSkills] = useState([]);
    const [resumeSummary, setResumeSummary] = useState('');

    // Academic fields state
    const [tenthPercentage, setTenthPercentage] = useState('');
    const [twelfthPercentage, setTwelfthPercentage] = useState('');
    const [collegeCgpa, setCollegeCgpa] = useState('');
    const [amcatScore, setAmcatScore] = useState('');
    const [academicLoading, setAcademicLoading] = useState(false);
    const [academicMessage, setAcademicMessage] = useState({ type: '', text: '' });
    const [fetchingAcademic, setFetchingAcademic] = useState(true);

    // Fetch academic data on mount
    useEffect(() => {
        const fetchProfile = async () => {
            if (!user.email) {
                setFetchingAcademic(false);
                return;
            }
            try {
                const res = await fetch(`${API_URL}/api/profile?email=${encodeURIComponent(user.email)}`);
                const data = await res.json();
                if (res.ok) {
                    setFullName(data.full_name ?? user.fullName);
                    setDepartment(data.department ?? user.department);
                    setProfilePicture(data.profile_picture ?? null);
                    setTenthPercentage(data.tenth_percentage ?? '');
                    setTwelfthPercentage(data.twelfth_percentage ?? '');
                    setCollegeCgpa(data.college_cgpa ?? '');
                    setAmcatScore(data.amcat_score ?? '');
                    setSkills(data.skills ?? []);
                    setResumeSummary(data.resume_summary ?? '');
                }
            } catch (err) {
                console.error('Failed to fetch profile:', err);
            } finally {
                setFetchingAcademic(false);
            }
        };
        fetchProfile();
    }, []);

    const handleLogout = () => {
        localStorage.clear();
        navigate('/');
    };

    const handlePasswordChange = async (e) => {
        e.preventDefault();
        if (newPassword !== confirmPassword) {
            setMessage({ type: 'error', text: 'Passwords do not match' });
            return;
        }

        setLoading(true);
        setMessage({ type: '', text: '' });

        try {
            const response = await fetch(`${API_URL}/api/change-password`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    email: user.email,
                    currentPassword,
                    newPassword,
                    role: user.role
                })
            });

            const data = await response.json();

            if (response.ok) {
                setMessage({ type: 'success', text: 'Password updated successfully!' });
                setCurrentPassword('');
                setNewPassword('');
                setConfirmPassword('');
            } else {
                setMessage({ type: 'error', text: data.error || 'Failed to update password' });
            }
        } catch (err) {
            setMessage({ type: 'error', text: 'Connection error. Please try again.' });
        } finally {
            setLoading(false);
        }
    };

    const handleInfoSave = async (e) => {
        e.preventDefault();
        setInfoLoading(true);
        setInfoMessage({ type: '', text: '' });

        try {
            const response = await fetch(`${API_URL}/api/profile`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    email: user.email,
                    full_name: fullName,
                    department: department,
                    profile_picture: profilePicture
                })
            });

            const data = await response.json();

            if (response.ok) {
                // Update localStorage
                const updatedUser = { ...user, fullName, department, profilePicture };
                localStorage.setItem('user', JSON.stringify(updatedUser));
                setInfoMessage({ type: 'success', text: 'Personal info updated!' });
            } else {
                setInfoMessage({ type: 'error', text: data.error || 'Failed to update info' });
            }
        } catch (err) {
            setInfoMessage({ type: 'error', text: 'Connection error.' });
        } finally {
            setInfoLoading(false);
        }
    };

    const handleImageUpload = (e) => {
        const file = e.target.files[0];
        if (file) {
            if (file.size > 2 * 1024 * 1024) {
                setInfoMessage({ type: 'error', text: 'Image too large (Max 2MB)' });
                return;
            }
            const reader = new FileReader();
            reader.onloadend = () => {
                setProfilePicture(reader.result);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleAcademicSave = async (e) => {
        e.preventDefault();
        setAcademicMessage({ type: '', text: '' });

        // Client-side validation
        const errors = [];
        if (tenthPercentage !== '' && (isNaN(tenthPercentage) || tenthPercentage < 0 || tenthPercentage > 100)) {
            errors.push('10th Percentage must be between 0 and 100');
        }
        if (twelfthPercentage !== '' && (isNaN(twelfthPercentage) || twelfthPercentage < 0 || twelfthPercentage > 100)) {
            errors.push('12th Percentage must be between 0 and 100');
        }
        if (collegeCgpa !== '' && (isNaN(collegeCgpa) || collegeCgpa < 0 || collegeCgpa > 10)) {
            errors.push('College CGPA must be between 0 and 10');
        }
        if (amcatScore !== '' && (isNaN(amcatScore) || !Number.isInteger(Number(amcatScore)) || Number(amcatScore) < 0)) {
            errors.push('AMCAT Score must be a non-negative integer');
        }

        if (errors.length > 0) {
            setAcademicMessage({ type: 'error', text: errors.join('; ') });
            return;
        }

        setAcademicLoading(true);

        try {
            const response = await fetch(`${API_URL}/api/profile`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    email: user.email,
                    tenth_percentage: tenthPercentage === '' ? null : parseFloat(tenthPercentage),
                    twelfth_percentage: twelfthPercentage === '' ? null : parseFloat(twelfthPercentage),
                    college_cgpa: collegeCgpa === '' ? null : parseFloat(collegeCgpa),
                    amcat_score: amcatScore === '' ? null : parseInt(amcatScore)
                })
            });

            const data = await response.json();

            if (response.ok) {
                setAcademicMessage({ type: 'success', text: 'Academic details saved successfully!' });
            } else {
                setAcademicMessage({ type: 'error', text: data.error || 'Failed to save academic details' });
            }
        } catch (err) {
            setAcademicMessage({ type: 'error', text: 'Connection error. Please try again.' });
        } finally {
            setAcademicLoading(false);
        }
    };

    return (
        <div className="profile-container">
            <div className="profile-header">
                <div className="profile-header-content">
                    <div>
                        <h1>Student Profile</h1>
                        <p>Manage your account information and security</p>
                    </div>
                    <button className="profile-logout-btn" onClick={handleLogout}>
                        <LogOut size={18} />
                        <span>Sign Out</span>
                    </button>
                </div>
            </div>

            <div className="profile-grid">
                {/* Info Section */}
                <div className="profile-card info-card glass">
                    <div className="card-header">
                        <User size={20} />
                        <h2>Personal Information</h2>
                    </div>
                    
                    <div className="avatar-upload-section">
                        <div className="avatar-preview-lg">
                            {profilePicture ? (
                                <img src={profilePicture} alt="Profile" className="object-cover w-full h-full" />
                            ) : (
                                <div className="avatar-placeholder-lg">
                                    {fullName?.[0] || user.fullName?.[0] || 'U'}
                                </div>
                            )}
                            <label className="avatar-edit-overlay">
                                <UploadCloud size={20} />
                                <input type="file" accept="image/*" onChange={handleImageUpload} className="hidden" />
                            </label>
                        </div>
                        <div className="avatar-info">
                            <h3>Profile Picture</h3>
                            <p>Recommended: Square JPG or PNG, max 2MB</p>
                        </div>
                    </div>

                    <form onSubmit={handleInfoSave} className="info-form">
                        <div className="info-grid">
                            <div className="info-item">
                                <label><User size={14} /> Full Name</label>
                                <input 
                                    type="text" 
                                    value={fullName} 
                                    onChange={(e) => setFullName(e.target.value)}
                                    placeholder="Enter full name"
                                    className="info-input"
                                />
                            </div>
                            <div className="info-item">
                                <label><Mail size={14} /> Email Address</label>
                                <div className="info-value readonly">{user.email}</div>
                            </div>
                            <div className="info-item">
                                <label><Hash size={14} /> ID Number</label>
                                <div className="info-value readonly">{user.idNumber}</div>
                            </div>
                            <div className="info-item">
                                <label><BookOpen size={14} /> Department</label>
                                <input 
                                    type="text" 
                                    value={department} 
                                    onChange={(e) => setDepartment(e.target.value)}
                                    placeholder="Enter department"
                                    className="info-input"
                                />
                            </div>
                        </div>
                        {infoMessage.text && (
                            <div className={`message-banner ${infoMessage.type} small`}>
                                {infoMessage.type === 'success' ? <CheckCircle2 size={14} /> : <AlertCircle size={14} />}
                                <span>{infoMessage.text}</span>
                            </div>
                        )}
                        <button type="submit" className="submit-btn info-save-btn" disabled={infoLoading}>
                            {infoLoading ? 'Saving...' : 'Save Info'}
                        </button>
                    </form>
                </div>

                {/* Password Section */}
                <div className="profile-card password-card glass">
                    <div className="card-header">
                        <Lock size={20} />
                        <h2>Security Settings</h2>
                    </div>
                    <form onSubmit={handlePasswordChange} className="password-form">
                        <div className="form-group">
                            <label>Current Password</label>
                            <input
                                type="password"
                                value={currentPassword}
                                onChange={(e) => setCurrentPassword(e.target.value)}
                                required
                                placeholder="••••••••"
                            />
                        </div>
                        <div className="form-group">
                            <label>New Password</label>
                            <input
                                type="password"
                                value={newPassword}
                                onChange={(e) => setNewPassword(e.target.value)}
                                required
                                placeholder="Minimum 6 characters"
                            />
                        </div>
                        <div className="form-group">
                            <label>Confirm New Password</label>
                            <input
                                type="password"
                                value={confirmPassword}
                                onChange={(e) => setConfirmPassword(e.target.value)}
                                required
                                placeholder="••••••••"
                            />
                        </div>

                        {message.text && (
                            <div className={`message-banner ${message.type}`}>
                                {message.type === 'success' ? <CheckCircle2 size={16} /> : <AlertCircle size={16} />}
                                <span>{message.text}</span>
                            </div>
                        )}

                        <button type="submit" className="submit-btn" disabled={loading}>
                            {loading ? 'Updating...' : 'Update Password'}
                        </button>
                    </form>
                </div>

                {/* Skills & AI Highlights Card */}
                <div className="profile-card skills-highlight-card glass">
                    <div className="card-header">
                        <Award size={20} className="text-[#F97316]" />
